package org.springframework.samples.petclinic.rest.function.owner;

import java.time.LocalDate;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.escalation.DailyOwnerLimitException;

/**
 * Rejects creating an owner once {@value #DAILY_LIMIT} owners have already been
 * registered on the new owner's registration day — by throwing
 * {@link DailyOwnerLimitException} (400).
 */
public class CheckDailyOwnerLimit {

    static final int DAILY_LIMIT = 20;

    public void service(@Val Owner owner, OwnerRepository ownerRepository)
            throws DailyOwnerLimitException {
        LocalDate day = owner.getRegistrationDate();
        if (day == null) {
            day = LocalDate.now();
        }
        long registeredToday = 0;
        for (Owner existing : ownerRepository.findAll()) {
            if (day.equals(existing.getRegistrationDate())) {
                registeredToday++;
            }
        }
        if (registeredToday >= DAILY_LIMIT) {
            throw new DailyOwnerLimitException(
                    "No more than " + DAILY_LIMIT + " owners may be registered per day");
        }
    }
}
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Objects;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.escalation.DuplicateOwnerException;

/**
 * Rejects creating an owner whose telephone number is already used by any other owner —
 * by throwing {@link DuplicateOwnerException} (409).
 *
 * <p>Duplicate detection is insensitive to letter case and to surrounding or repeated
 * whitespace: {@code "  john   smith "} and {@code "John Smith"} are treated as the same
 * value (see {@link #normalize(String)}).
 */
public class CheckDuplicateOwner {

    public void service(@Val Owner owner, OwnerRepository ownerRepository)
            throws DuplicateOwnerException {
        String telephone = normalize(owner.getTelephone());
        String email = normalize(owner.getEmail());
        boolean hasEmail = !email.isEmpty();
        for (Owner existing : ownerRepository.findAll()) {
            if (Objects.equals(existing.getId(), owner.getId())) {
                continue;
            }
            if (Objects.equals(normalize(existing.getTelephone()), telephone)) {
                throw new DuplicateOwnerException(
                        "An owner with the same telephone already exists");
            }
            if (hasEmail && Objects.equals(normalize(existing.getEmail()), email)) {
                throw new DuplicateOwnerException(
                        "An owner with the same email already exists");
            }
        }
    }

    /**
     * Normalizes a value for duplicate comparison: {@code null} becomes empty, letter
     * case is folded to lower case, surrounding whitespace is trimmed and any run of
     * internal whitespace is collapsed to a single space.
     */
    static String normalize(String value) {
        if (value == null) {
            return "";
        }
        return value.trim().replaceAll("\\s+", " ").toLowerCase();
    }
}
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Canonicalizes the city of a newly created owner.
 *
 * <p>The city is title-cased (each whitespace-separated word capitalized, the rest of
 * the word lower-cased) so {@code "riverdale"} becomes {@code "Riverdale"}. However, if
 * an owner already exists in that city — matched case-insensitively — the existing
 * owner's exact spelling of the city name is reused instead, so a city is spelled
 * consistently across all owners.
 */
public class NormalizeCity {

    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
        String city = owner.getCity();
        if (city == null) {
            return;
        }
        for (Owner existing : ownerRepository.findAll()) {
            if (existing.getCity() != null && existing.getCity().equalsIgnoreCase(city)) {
                owner.setCity(existing.getCity());
                return;
            }
        }
        owner.setCity(titleCase(city));
    }

    /**
     * Title-cases a value: each whitespace-separated word has its first letter
     * upper-cased and its remaining letters lower-cased.
     */
    static String titleCase(String value) {
        StringBuilder result = new StringBuilder(value.length());
        boolean startOfWord = true;
        for (int i = 0; i < value.length(); i++) {
            char c = value.charAt(i);
            if (Character.isWhitespace(c)) {
                startOfWord = true;
                result.append(c);
            }
            else if (startOfWord) {
                result.append(Character.toUpperCase(c));
                startOfWord = false;
            }
            else {
                result.append(Character.toLowerCase(c));
            }
        }
        return result.toString();
    }
}
